:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #263b3c;
  background: #dcebe4;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 40px 18px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 15% 15%, #f2e7bf 0 7%, transparent 7.2%), #dcebe4;
}
.card {
  width: min(100%, 620px);
  padding: clamp(24px, 6vw, 42px);
  border: 2px solid #263b3c;
  border-radius: 18px;
  background: #fffdf6;
  box-shadow: 8px 8px 0 #8ab5a5;
}
.header { display: flex; align-items: center; gap: 15px; margin-bottom: 28px; }
.pixel-mark { display: grid; place-items: center; width: 52px; height: 52px; border: 2px solid #263b3c; border-radius: 12px; background: #f2cc68; font-size: 28px; }
.eyebrow, .small-label { margin: 0 0 3px; color: #55706b; font-size: 12px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(28px, 7vw, 36px); line-height: 1.1; }
h2 { margin: 0; font-size: 19px; }
.note-form { display: grid; gap: 10px; }
label { margin-top: 4px; font-weight: 700; }
.hint { color: #71817c; font-size: 14px; font-weight: 500; }
textarea, input { width: 100%; padding: 12px 14px; border: 1.5px solid #9ab2a8; border-radius: 9px; background: white; color: #263b3c; font: inherit; }
textarea { resize: vertical; min-height: 82px; }
textarea:focus, input:focus { outline: 3px solid #f2cc68; outline-offset: 2px; border-color: #263b3c; }
button { font: inherit; cursor: pointer; }
.primary-button { justify-self: start; margin-top: 4px; padding: 11px 18px; border: 2px solid #263b3c; border-radius: 9px; background: #263b3c; color: white; font-weight: 750; }
.primary-button:hover { background: #395957; }
.primary-button:active, .tag-button:active, .clear-button:active { transform: translateY(2px); }
button:focus-visible { outline: 3px solid #d49c2f; outline-offset: 3px; }
.tag-section, .notes-section { margin-top: 30px; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; }
.tag-list { display: flex; flex-wrap: wrap; gap: 9px; }
.tag-button { padding: 7px 11px; border: 1.5px solid #8ab5a5; border-radius: 999px; background: #e8f2ec; color: #263b3c; }
.tag-button:hover { background: #d5e8dc; }
.tag-button[aria-pressed="true"] { border-color: #263b3c; background: #f2cc68; }
.tag-count { margin-left: 5px; color: #55706b; font-size: 14px; font-weight: 750; }
.total { color: #71817c; font-size: 15px; font-weight: 500; }
.filter-status { display: flex; align-items: center; gap: 8px; color: #55706b; font-size: 14px; }
.clear-button { padding: 4px 9px; border: 1px solid #9ab2a8; border-radius: 7px; background: transparent; color: #263b3c; }
.clear-button:hover { background: #e8f2ec; }
.notes-list { display: grid; gap: 11px; margin: 0; padding: 0; list-style: none; }
.note { padding: 15px; border: 1.5px solid #d1dfd6; border-radius: 10px; background: white; }
.note-text { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.5; }
.note-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 11px; }
.note-tag { padding: 3px 8px; border-radius: 999px; background: #e8f2ec; color: #55706b; font-size: 14px; }
.empty-state { margin: 0; padding: 18px; border: 1px dashed #9ab2a8; border-radius: 10px; color: #71817c; text-align: center; }
footer { margin-top: 28px; color: #71817c; font-size: 14px; text-align: center; }
@media (max-width: 420px) { body { padding: 20px 12px; } .card { padding: 22px 18px; } .section-heading { align-items: flex-start; } }

const form = document.querySelector('#note-form');
const textInput = document.querySelector('#note-text');
const tagsInput = document.querySelector('#note-tags');
const notesList = document.querySelector('#notes-list');
const tagList = document.querySelector('#tag-list');
const noteTotal = document.querySelector('#note-total');
const emptyState = document.querySelector('#empty-state');
const filterStatus = document.querySelector('#filter-status');
const activeFilter = document.querySelector('#active-filter');
const clearFilter = document.querySelector('#clear-filter');

let notes = [];
let selectedTag = null;

function parseTags(value) {
  return [...new Set(value.split(',').map(tag => tag.trim()).filter(Boolean))];
}

function render() {
  const counts = new Map();
  notes.forEach(note => note.tags.forEach(tag => counts.set(tag, (counts.get(tag) || 0) + 1)));
  tagList.replaceChildren();
  [...counts.keys()].sort((a, b) => a.localeCompare(b)).forEach(tag => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'tag-button';
    button.setAttribute('aria-pressed', String(selectedTag === tag));
    button.setAttribute('aria-label', `Filter by ${tag}, ${counts.get(tag)} ${counts.get(tag) === 1 ? 'note' : 'notes'}`);
    button.append(document.createTextNode(tag));
    const count = document.createElement('span');
    count.className = 'tag-count';
    count.textContent = counts.get(tag);
    button.append(count);
    button.addEventListener('click', () => {
      selectedTag = selectedTag === tag ? null : tag;
      render();
    });
    tagList.append(button);
  });

  const shown = selectedTag ? notes.filter(note => note.tags.includes(selectedTag)) : notes;
  notesList.replaceChildren();
  shown.forEach(note => {
    const item = document.createElement('li');
    item.className = 'note';
    const content = document.createElement('p');
    content.className = 'note-text';
    content.textContent = note.text;
    item.append(content);
    if (note.tags.length) {
      const noteTags = document.createElement('div');
      noteTags.className = 'note-tags';
      note.tags.forEach(tag => {
        const chip = document.createElement('span');
        chip.className = 'note-tag';
        chip.textContent = tag;
        noteTags.append(chip);
      });
      item.append(noteTags);
    }
    notesList.append(item);
  });

  noteTotal.textContent = `(${shown.length}${selectedTag ? ` of ${notes.length}` : ''})`;
  emptyState.hidden = shown.length > 0;
  emptyState.textContent = selectedTag ? `No notes tagged “${selectedTag}”.` : 'Your page is waiting for its first note. ✨';
  filterStatus.hidden = !selectedTag;
  activeFilter.textContent = selectedTag ? `Filtered: ${selectedTag}` : '';
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = textInput.value.trim();
  if (!text) return;
  notes.unshift({ text, tags: parseTags(tagsInput.value) });
  form.reset();
  textInput.focus();
  render();
});

clearFilter.addEventListener('click', () => {
  selectedTag = null;
  render();
});

render();
